CREATE TABLE "c_BillingAccount" ("id" BIGINT NOT NULL, "a_BillingAccount_balance" NUMERIC NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Department" ("id" BIGINT NOT NULL, "a_Department_name" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Encounter" ("id" BIGINT NOT NULL, "a_Encounter_admit_time" TIMESTAMP NOT NULL, "a_Encounter_discharge_time" TIMESTAMP, "r_PatientEncounters_source_id" BIGINT, PRIMARY KEY ("id"), CHECK ((TRUE) OR "r_PatientEncounters_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_PatientEncounters_source_id" IS NOT NULL));
CREATE TABLE "c_InsurancePlan" ("id" BIGINT NOT NULL, "a_InsurancePlan_payer" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_OrderRequest" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_LabOrder_specimen" TEXT, "a_MedicationOrder_route" TEXT, "a_OrderRequest_priority" TEXT, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('LabOrder','MedicationOrder','OrderRequest')), CHECK ((dtype IN ('LabOrder')) OR "a_LabOrder_specimen" IS NULL), CHECK (NOT (dtype IN ('LabOrder')) OR "a_LabOrder_specimen" IS NOT NULL), CHECK ((dtype IN ('MedicationOrder')) OR "a_MedicationOrder_route" IS NULL), CHECK (NOT (dtype IN ('MedicationOrder')) OR "a_MedicationOrder_route" IS NOT NULL), CHECK ((dtype IN ('LabOrder','MedicationOrder','OrderRequest')) OR "a_OrderRequest_priority" IS NULL), CHECK (NOT (dtype IN ('LabOrder','MedicationOrder','OrderRequest')) OR "a_OrderRequest_priority" IS NOT NULL));
CREATE TABLE "c_Patient" ("id" BIGINT NOT NULL, "a_Person_name" TEXT NOT NULL, "a_Person_dob" DATE NOT NULL, "a_Patient_mrn" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Person" ("id" BIGINT NOT NULL, "a_Person_name" TEXT NOT NULL, "a_Person_dob" DATE NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Provider" ("id" BIGINT NOT NULL, "a_Person_name" TEXT NOT NULL, "a_Person_dob" DATE NOT NULL, "a_Provider_credential" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Result" ("id" BIGINT NOT NULL, "a_Result_value_text" TEXT NOT NULL, "r_OrderResults_source_id" BIGINT, "r_OrderResults_source_dtype" TEXT, PRIMARY KEY ("id"), CHECK ("r_OrderResults_source_dtype" IS NULL OR "r_OrderResults_source_dtype" IN ('LabOrder','MedicationOrder','OrderRequest')), CHECK ((TRUE) OR "r_OrderResults_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_OrderResults_source_id" IS NOT NULL));
CREATE TABLE "l_DepartmentProviders" ("r_DepartmentProviders_source_id" BIGINT NOT NULL, "r_DepartmentProviders_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_DepartmentProviders_source_id", "r_DepartmentProviders_target_id"), UNIQUE ("r_DepartmentProviders_target_id"));
CREATE TABLE "l_EncounterOrders" ("r_EncounterOrders_source_id" BIGINT NOT NULL, "r_EncounterOrders_target_id" BIGINT NOT NULL, "r_EncounterOrders_target_dtype" TEXT NOT NULL, PRIMARY KEY ("r_EncounterOrders_source_id", "r_EncounterOrders_target_id"), UNIQUE ("r_EncounterOrders_target_id"), CHECK ("r_EncounterOrders_target_dtype" IS NULL OR "r_EncounterOrders_target_dtype" IN ('LabOrder','MedicationOrder','OrderRequest')));
CREATE TABLE "l_PatientBilling" ("r_PatientBilling_source_id" BIGINT NOT NULL, "r_PatientBilling_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_PatientBilling_source_id", "r_PatientBilling_target_id"), UNIQUE ("r_PatientBilling_target_id"), UNIQUE ("r_PatientBilling_source_id"));
CREATE TABLE "l_PatientPlans" ("r_PatientPlans_source_id" BIGINT NOT NULL, "r_PatientPlans_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_PatientPlans_source_id", "r_PatientPlans_target_id"));
CREATE TABLE "l_ProviderEncounters" ("r_ProviderEncounters_source_id" BIGINT NOT NULL, "r_ProviderEncounters_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_ProviderEncounters_source_id", "r_ProviderEncounters_target_id"));
ALTER TABLE "c_Encounter" ADD CONSTRAINT "fk_c_Encounter_0" FOREIGN KEY ("r_PatientEncounters_source_id") REFERENCES "c_Patient" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_Result" ADD CONSTRAINT "fk_c_Result_0" FOREIGN KEY ("r_OrderResults_source_id", "r_OrderResults_source_dtype") REFERENCES "c_OrderRequest" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_DepartmentProviders" ADD CONSTRAINT "fk_l_DepartmentProviders_0" FOREIGN KEY ("r_DepartmentProviders_source_id") REFERENCES "c_Department" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_DepartmentProviders" ADD CONSTRAINT "fk_l_DepartmentProviders_1" FOREIGN KEY ("r_DepartmentProviders_target_id") REFERENCES "c_Provider" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_EncounterOrders" ADD CONSTRAINT "fk_l_EncounterOrders_0" FOREIGN KEY ("r_EncounterOrders_source_id") REFERENCES "c_Encounter" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_EncounterOrders" ADD CONSTRAINT "fk_l_EncounterOrders_1" FOREIGN KEY ("r_EncounterOrders_target_id", "r_EncounterOrders_target_dtype") REFERENCES "c_OrderRequest" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PatientBilling" ADD CONSTRAINT "fk_l_PatientBilling_0" FOREIGN KEY ("r_PatientBilling_source_id") REFERENCES "c_Patient" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PatientBilling" ADD CONSTRAINT "fk_l_PatientBilling_1" FOREIGN KEY ("r_PatientBilling_target_id") REFERENCES "c_BillingAccount" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PatientPlans" ADD CONSTRAINT "fk_l_PatientPlans_0" FOREIGN KEY ("r_PatientPlans_source_id") REFERENCES "c_Patient" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PatientPlans" ADD CONSTRAINT "fk_l_PatientPlans_1" FOREIGN KEY ("r_PatientPlans_target_id") REFERENCES "c_InsurancePlan" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_ProviderEncounters" ADD CONSTRAINT "fk_l_ProviderEncounters_0" FOREIGN KEY ("r_ProviderEncounters_source_id") REFERENCES "c_Provider" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_ProviderEncounters" ADD CONSTRAINT "fk_l_ProviderEncounters_1" FOREIGN KEY ("r_ProviderEncounters_target_id") REFERENCES "c_Encounter" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
CREATE FUNCTION "require_DepartmentProviders"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Provider" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_DepartmentProviders" l WHERE l."r_DepartmentProviders_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: DepartmentProviders'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_DepartmentProviders_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Provider" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_DepartmentProviders"();
CREATE CONSTRAINT TRIGGER "ct_DepartmentProviders_link" AFTER INSERT OR UPDATE OR DELETE ON "l_DepartmentProviders" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_DepartmentProviders"();
CREATE FUNCTION "require_EncounterOrders"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_OrderRequest" t WHERE (t.dtype IN ('LabOrder','MedicationOrder','OrderRequest')) AND NOT EXISTS (SELECT 1 FROM "l_EncounterOrders" l WHERE l."r_EncounterOrders_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: EncounterOrders'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_EncounterOrders_target" AFTER INSERT OR UPDATE OR DELETE ON "c_OrderRequest" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_EncounterOrders"();
CREATE CONSTRAINT TRIGGER "ct_EncounterOrders_link" AFTER INSERT OR UPDATE OR DELETE ON "l_EncounterOrders" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_EncounterOrders"();
CREATE FUNCTION "require_PatientBilling"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_BillingAccount" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_PatientBilling" l WHERE l."r_PatientBilling_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: PatientBilling'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_PatientBilling_target" AFTER INSERT OR UPDATE OR DELETE ON "c_BillingAccount" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_PatientBilling"();
CREATE CONSTRAINT TRIGGER "ct_PatientBilling_link" AFTER INSERT OR UPDATE OR DELETE ON "l_PatientBilling" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_PatientBilling"();